styl:
table.cta.cta-primary { margin: 16px auto; }
table.cta.cta-primary td.butt { background-color: {{ bg_color }}; border-radius: {{ radius }}px; padding: 0; }
table.cta.cta-primary a.butt-link { display: inline-block; padding: 12px 28px; font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: 16px; color: {{ text_color }}; text-decoration: none; line-height: 1; }
